@php
    $verification = $user->clientVerification;
    $verificationStatus = $verification?->status ?? 'not-submitted';
    $verificationLabel = match ($verificationStatus) { 'approved' => 'Verified', 'pending' => 'Under review', 'rejected' => 'Action required', default => 'Not submitted' };
    $verificationClass = match ($verificationStatus) { 'approved' => 'badge-success', 'pending' => 'badge-warning', 'rejected' => 'badge-danger', default => 'badge-neutral' };
    $canSubmitVerification = ! $verification || $verification->status === 'rejected';
    $canCaptureLegacySignature = $verificationStatus === 'approved' && ! $verification?->digital_signature;
    $canUpdatePayslip = $verificationStatus === 'approved';
    $detailsComplete = (bool) $verification;
    $documentsComplete = filled($user->profile_photo_path) && filled($verification?->valid_id_path) && filled($verification?->selfie_with_id_path);
    $signatureComplete = filled($verification?->digital_signature);
    $approvalComplete = $verificationStatus === 'approved';
    $completedSteps = collect([$detailsComplete, $documentsComplete, $signatureComplete, $approvalComplete])->filter()->count();
    $progress = $completedSteps * 25;
@endphp
