<script data-partial-page-script>
const verificationForm=document.getElementById('verification-form');const employmentStatus=document.getElementById('employment-status');
if(verificationForm&&employmentStatus){const fields=[...document.querySelectorAll('[data-employment-field]')];const inputs=[document.getElementById('company-name'),document.getElementById('job-title')];const sync=()=>{const required=['employed','self_employed'].includes(employmentStatus.value);fields.forEach(field=>{field.hidden=!required;});inputs.forEach(input=>{if(input){input.required=required;input.disabled=!required;}});};employmentStatus.addEventListener('change',sync);sync();}
document.querySelectorAll('[data-file-input]').forEach(input=>{const update=()=>{const card=input.nextElementSibling;const name=card?.querySelector('[data-file-name]');if(!name)return;name.textContent=input.files?.[0]?.name||name.dataset.default;card.classList.toggle('has-file',Boolean(input.files?.length)||card.dataset.existing==='true');};input.addEventListener('change',update);input.addEventListener('verification-upload:prepared',update);});
</script>
